// ML_KEM_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module ML_KEM_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [1:0] c_op,
  input logic [1:0] c_pset,
  input logic  c_hr_en,
  input logic [10:0] c_hp_addr,
  input logic  c_start,
  input logic  c_hp_load,
  input logic [31:0] c_hw_data,
  input logic [31:0] c_hr_data,
  input logic  c_busy,
  input logic  c_hw_valid,
  input logic  c_hw_ready,
  input logic  c_hr_valid,
  input logic  c_hr_ready,
  input logic  c_done,
  input logic  c_err
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 11;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:10];          // model of every stored word
  logic [4:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;
  logic m_state_DATA_IN;          // full / valid pulse / available
  logic m_state_DATA_OUT;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_done) m_set[0] = 1'b1;
    if (c_err) m_set[1] = 1'b1;
    if (m_state_DATA_IN && c_hw_ready) m_set[2] = 1'b1;
    if (m_wr && m_map && (m_idx == 8) && m_state_DATA_IN) m_set[3] = 1'b1;
    if (c_hr_valid && !m_state_DATA_OUT) m_set[4] = 1'b1;
    if (c_hr_valid && m_state_DATA_OUT && (m_rd && m_map && m_idx == 9)) m_set[4] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_pulse_CMD <= 0;
      m_state_DATA_IN <= 0;
      m_state_DATA_OUT <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h1F;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h1F;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'h7FF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 7) ? PWDATA & m_be & 32'h3 : 0;
      if (m_wr && m_map && m_idx == 8 && !m_state_DATA_IN) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 8 && !m_state_DATA_IN) m_state_DATA_IN <= 1;
      if (m_state_DATA_IN && c_hw_ready) m_state_DATA_IN <= 0;
      if (c_hr_valid && (!m_state_DATA_OUT || (m_rd && m_map && m_idx == 9))) begin
        m_w[9] <= (32'(c_hr_data[31:0]) << 0);
        m_state_DATA_OUT <= 1;
      end else if ((m_rd && m_map && m_idx == 9)) m_state_DATA_OUT <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h4D4B0101;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_DATA_OUT, m_state_DATA_IN});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return 0;
      8: return m_w[8];
      9: return m_w[9];
      10: return (32'(c_busy) << 0);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][4:0] & m_w[2][4:0]))
  `SVA_INV(a_core_op, c_op == m_w[5][1:0])
  `SVA_INV(a_core_pset, c_pset == m_w[5][3:2])
  `SVA_INV(a_core_hr_en, c_hr_en == m_w[5][4:4])
  `SVA_INV(a_core_hp_addr, c_hp_addr == m_w[6][10:0])
  `SVA_INV(a_core_start, c_start == m_pulse_CMD[0])
  `SVA_INV(a_core_hp_load, c_hp_load == m_pulse_CMD[1])
  `SVA_INV(a_core_hw_data, c_hw_data == m_w[8][31:0])
  `SVA_INV(a_core_hw_valid, c_hw_valid == m_state_DATA_IN)
  `SVA_INV(a_core_hr_ready, c_hr_ready == (!m_state_DATA_OUT || (m_rd && m_map && m_idx == 9)))
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_op == 2'h0 && c_pset == 2'h0 && c_hr_en == 1'h0 && c_hp_addr == 11'h0 && c_start == 1'h0 && c_hp_load == 1'h0 && c_hw_data == 32'h0 && !c_hw_valid && c_hr_ready)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CTRL, m_rd && m_map && m_idx == 5)
  `FC(wr_CTRL, m_wr && m_map && m_idx == 5)
  `FC(rd_PTR, m_rd && m_map && m_idx == 6)
  `FC(wr_PTR, m_wr && m_map && m_idx == 6)
  `FC(rd_CMD, m_rd && m_map && m_idx == 7)
  `FC(wr_CMD, m_wr && m_map && m_idx == 7)
  `FC(rd_DATA_IN, m_rd && m_map && m_idx == 8)
  `FC(wr_DATA_IN, m_wr && m_map && m_idx == 8)
  `FC(rd_DATA_OUT, m_rd && m_map && m_idx == 9)
  `FC(wr_DATA_OUT, m_wr && m_map && m_idx == 9)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 10)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 10)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_DONE_set, m_set[0])
  `FC(irq_DONE_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_DONE_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_DONE_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_ERR_set, m_set[1])
  `FC(irq_ERR_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_ERR_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_ERR_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_DATA_IN_DONE_set, m_set[2])
  `FC(irq_DATA_IN_DONE_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_DATA_IN_DONE_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_DATA_IN_DONE_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_DATA_IN_OVF_set, m_set[3])
  `FC(irq_DATA_IN_OVF_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_DATA_IN_OVF_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_DATA_IN_OVF_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_DATA_OUT_AVAIL_set, m_set[4])
  `FC(irq_DATA_OUT_AVAIL_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_DATA_OUT_AVAIL_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_DATA_OUT_AVAIL_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(cmd_start, m_pulse_CMD[0])
  `FC(cmd_hp_load, m_pulse_CMD[1])
  `FC(DATA_IN_handshake, m_state_DATA_IN && c_hw_ready)
  `FC(DATA_IN_backpressure, m_state_DATA_IN && !c_hw_ready)
  `FC(DATA_IN_write_while_full, m_wr && m_map && m_idx == 8 && m_state_DATA_IN)
  `FC(DATA_OUT_capture, c_hr_valid && !m_state_DATA_OUT)
  `FC(DATA_OUT_backpressure, c_hr_valid && m_state_DATA_OUT && !(m_rd && m_map && m_idx == 9))
  `FC(DATA_OUT_pop, m_rd && m_map && m_idx == 9 && m_state_DATA_OUT)
  `FC(DATA_OUT_read_empty, m_rd && m_map && m_idx == 9 && !m_state_DATA_OUT)
  `FC(DATA_OUT_pop_and_capture, c_hr_valid && m_state_DATA_OUT && m_rd && m_map && m_idx == 9)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind ML_KEM_apb ML_KEM_apb_sva u_apb_sva (.*);
